def shipping_fee(weight_grams, expedited=False):
    if type(weight_grams) is not int or type(expedited) is not bool:
        raise TypeError
    if weight_grams < 1 or weight_grams > 6000:
        raise ValueError

    extra = max(0, (weight_grams - 1000) // 1000)
    return 600 + extra * 200 + (400 if expedited else 0)

